import{_ as r,o as a,c as t,a2 as n}from"./chunks/framework.DaGSOal_.js";const h=JSON.parse('{"title":"W","description":"","frontmatter":{},"headers":[],"relativePath":"glossaire-a-z/w.md","filePath":"glossaire-a-z/w.md"}'),s={name:"glossaire-a-z/w.md"};function o(i,e,l,d,u,c){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="w" tabindex="-1">W <a class="header-anchor" href="#w" aria-label="Permalink to &quot;W&quot;">​</a></h1><h2 id="wallet-fr-portefeuille" tabindex="-1">Wallet (fr : Portefeuille) <a class="header-anchor" href="#wallet-fr-portefeuille" aria-label="Permalink to &quot;Wallet (fr : Portefeuille)&quot;">​</a></h2><p>Une application logicielle ou un dispositif qui stocke et gère les clés publiques et privées, permettant aux utilisateurs d’interagir avec une blockchain en envoyant, recevant et gérant leurs jetons et leurs transactions.</p><p>→ <a href="https://docs.cardano.org/about-cardano/new-to-cardano/types-of-wallets" target="_blank" rel="noreferrer">Cardano Docs — Types of wallets</a></p><p>→ <a href="https://docs.cardano.org/learn/cardano-keys/" target="_blank" rel="noreferrer">Cardano Docs — Cardano keys</a></p><h2 id="wallet-address-fr-adresse-de-portefeuille" tabindex="-1">Wallet Address (fr : Adresse de portefeuille) <a class="header-anchor" href="#wallet-address-fr-adresse-de-portefeuille" aria-label="Permalink to &quot;Wallet Address (fr : Adresse de portefeuille)&quot;">​</a></h2><p>Un identifiant alphanumérique unique dérivé de clés publiques qui désigne la destination des jetons sur une blockchain. Il permet aux participants d’envoyer et de recevoir des jetons de manière sécurisée tout en préservant leur pseudonymat. Sur Cardano, les adresses peuvent également contenir des informations liées au staking, qui les relient à la délégation et aux récompenses.</p><p>→ <a href="https://docs.cardano.org/learn/cardano-addresses/" target="_blank" rel="noreferrer">Cardano Docs — Cardano addresses</a></p><h2 id="wanchain" tabindex="-1">Wanchain <a class="header-anchor" href="#wanchain" aria-label="Permalink to &quot;Wanchain&quot;">​</a></h2><p>Une blockchain et un protocole d’interopérabilité qui permettent des transactions inter-chaînes bidirectionnelles et non dépositaires (<em>non-custodial</em>) avec plusieurs réseaux, dont Cardano.</p><p>→ <a href="https://docs.wanchain.org/products/wanbridge" target="_blank" rel="noreferrer">Wanchain Documentation — WanBridge</a></p><p>→ <a href="https://docs.wanchain.org/wallet-and-tools/wanchain-bridge-user-manual-new-version" target="_blank" rel="noreferrer">Wanchain Documentation — Guide de WanBridge avec un transfert d’ADA</a></p><h2 id="warm-wallet-fr-portefeuille-connecte-securise" tabindex="-1">Warm Wallet (fr : Portefeuille connecté sécurisé) <a class="header-anchor" href="#warm-wallet-fr-portefeuille-connecte-securise" aria-label="Permalink to &quot;Warm Wallet (fr : Portefeuille connecté sécurisé)&quot;">​</a></h2><p>Un portefeuille connecté à Internet, mais doté de fonctionnalités de sécurité renforcées par rapport aux portefeuilles connectés en permanence (<em>hot wallets</em>), souvent utilisé pour des solutions de conservation ou des applications d’entreprise. Il cherche à équilibrer accessibilité et protection.</p><h2 id="web2" tabindex="-1">Web2 <a class="header-anchor" href="#web2" aria-label="Permalink to &quot;Web2&quot;">​</a></h2><p>Web2 désigne l’ère d’Internet caractérisée par des plateformes interactives, du contenu généré par les utilisateurs, les réseaux sociaux et des services centralisés contrôlés par de grandes entreprises.</p><p>→ <a href="https://ethereum.org/fr/developers/docs/web2-vs-web3/" target="_blank" rel="noreferrer">Ethereum.org — Web2 vs Web3, en français</a></p><h2 id="web3" tabindex="-1">Web3 <a class="header-anchor" href="#web3" aria-label="Permalink to &quot;Web3&quot;">​</a></h2><p>Désigne le concept d’un Internet décentralisé reposant sur la blockchain, dans lequel les utilisateurs disposent d’un meilleur contrôle sur leurs données, leur identité et leurs interactions numériques.</p><p>→ <a href="https://ethereum.org/fr/web3/" target="_blank" rel="noreferrer">Ethereum.org — Qu’est-ce que le Web3 ?, en français</a></p><h2 id="working-group-fr-groupe-de-travail" tabindex="-1">Working Group (fr : Groupe de travail) <a class="header-anchor" href="#working-group-fr-groupe-de-travail" aria-label="Permalink to &quot;Working Group (fr : Groupe de travail)&quot;">​</a></h2><p>Un groupe réunissant des experts et des membres de la communauté afin de se concentrer sur un sujet spécifique au sein de l’écosystème Cardano.</p>',22)])])}const f=r(s,[["render",o]]);export{h as __pageData,f as default};
